chrome.action.onClicked.addListener(async e=>{if(e.id)try{await chrome.sidePanel.open({tabId:e.id})}catch(r){console.error("Error opening sidebar:",r)}});chrome.tabs.onUpdated.addListener(async(e,r,o)=>{if(r.status==="complete"&&o.url&&(o.url.includes("x.com")||o.url.includes("twitter.com")))try{await chrome.sidePanel.setOptions({tabId:e,path:"sidebar.html",enabled:!0})}catch(i){console.error("Error setting sidebar options:",i)}});
